module min_obstacles_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [4:0] m,\n    input wire [31:0] p,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // Constants and parameters\n    parameter N_MAX = 8;\n    parameter STATE_COUNT = 256; // 2^N_MAX\n    parameter M_MAX = 16;\n    \n    // State declarations\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] INIT_PRECOMP   = 4'd1;\n    localparam [3:0] INIT_DP        = 4'd2;\n    localparam [3:0] START_COLUMN   = 4'd3;\n    localparam [3:0] LOOP_CUR       = 4'd4;\n    localparam [3:0] LOOP_PREV      = 4'd5;\n    localparam [3:0] COMPUTE_CANDIDATE = 4'd6;\n    localparam [3:0] NEXT_PREV      = 4'd7;\n    localparam [3:0] NEXT_CUR       = 4'd8;\n    localparam [3:0] NEXT_COLUMN    = 4'd9;\n    localparam [3:0] FINALIZE       = 4'd10;\n    localparam [3:0] DONE_ST        = 4'd11;\n    \n    // Internal registers\n    reg [3:0] current_state, next_state;\n    reg [7:0] cur_state;\n    reg [7:0] prev_state;\n    reg [7:0] state_limit;\n    reg [7:0] col_index;\n    reg [7:0] popcount_cur;\n    reg [7:0] tmp_min;\n    reg [31:0] tmp_cnt;\n    reg [7:0] global_min;\n    reg [31:0] global_cnt;\n    \n    // DP arrays\n    reg [7:0] dp_prev_min [0:STATE_COUNT-1];\n    reg [31:0] dp_prev_cnt [0:STATE_COUNT-1];\n    reg [7:0] dp_new_min [0:STATE_COUNT-1];\n    reg [31:0] dp_new_cnt [0:STATE_COUNT-1];\n    \n    // Precomputed tables\n    reg [7:0] popcount_rom [0:STATE_COUNT-1];\n    reg valid_transition [0:STATE_COUNT-1][0:STATE_COUNT-1];\n    \n    // Counter registers\n    reg [7:0] calc_state;\n    reg [7:0] calc_state_i;\n    reg [7:0] calc_state_j;\n    integer i;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            current_state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            col_index <= 8'd0;\n            cur_state <= 8'd0;\n            prev_state <= 8'd0;\n            state_limit <= 8'd0;\n            popcount_cur <= 8'd0;\n            tmp_min <= 8'd255;\n            tmp_cnt <= 32'd0;\n            global_min <= 8'd255;\n            global_cnt <= 32'd0;\n            calc_state <= 8'd0;\n            calc_state_i <= 8'd0;\n            calc_state_j <= 8'd0;\n            \n            // Initialize arrays\n            for (i = 0; i < STATE_COUNT; i = i + 1) begin\n                dp_prev_min[i] <= 8'd255;\n                dp_prev_cnt[i] <= 32'd0;\n                dp_new_min[i] <= 8'd255;\n                dp_new_cnt[i] <= 32'd0;\n            end\n            \n            for (i = 0; i < STATE_COUNT; i = i + 1) begin\n                popcount_rom[i] <= 8'd0;\n            end\n            \n            for (i = 0; i < STATE_COUNT; i = i + 1) begin\n                for (integer j = 0; j < STATE_COUNT; j = j + 1) begin\n                    valid_transition[i][j] <= 1'b0;\n                end\n            end\n        end\n        else begin\n            current_state <= next_state;\n            \n            case (current_state)\n                INIT_PRECOMP: begin\n                    if (calc_state == 8'd0) begin\n                        calc_state <= 8'd1;\n                    end\n                    else if (calc_state == 8'd1) begin\n                        if (calc_state_i < STATE_COUNT) begin\n                            popcount_rom[calc_state_i] <= ^calc_state_i;\n                            calc_state_i <= calc_state_i + 8'd1;\n                        end\n                        else begin\n                            calc_state <= 8'd2;\n                            calc_state_i <= 8'd0;\n                        end\n                    end\n                    else if (calc_state == 8'd2) begin\n                        if (calc_state_i < STATE_COUNT) begin\n                            calc_state_j <= calc_state_j + 8'd1;\n                            if (calc_state_j < STATE_COUNT) begin\n                                if (calc_state_i[7:0] + calc_state_j[7:0] == 0) begin\n                                    valid_transition[calc_state_i][calc_state_j] <= 1'b1;\n                                end\n                                else begin\n                                    // Simplified validity check (actual algo needed)\n                                    valid_transition[calc_state_i][calc_state_j] <= (calc_state_i[0] | calc_state_j[0]); \n                                end\n                            end\n                            else begin\n                                calc_state_j <= 8'd0;\n                                calc_state_i <= calc_state_i + 8'd1;\n                            end\n                        end\n                        else begin\n                            next_state <= INIT_DP;\n                            calc_state <= 8'd0;\n                        end\n                    end\n                end\n                \n                INIT_DP: begin\n                    if (calc_state_i < STATE_COUNT) begin\n                        if (calc_state_i < (1 << n)) begin\n                            dp_prev_min[calc_state_i] <= popcount_rom[calc_state_i];\n                            dp_prev_cnt[calc_state_i] <= (popcount_rom[calc_state_i] < 8'd255) ? 32'd1 : 32'd0;\n                        end\n                        else begin\n                            dp_prev_min[calc_state_i] <= 8'd255;\n                            dp_prev_cnt[calc_state_i] <= 32'd0;\n                        end\n                        calc_state_i <= calc_state_i + 1;\n                    end\n                    else begin\n                        next_state <= START_COLUMN;\n                        calc_state_i <= 8'd0;\n                    end\n                end\n                \n                LOOP_CUR: begin\n                    if (cur_state < state_limit) begin\n                        popcount_cur <= popcount_rom[cur_state];\n                        tmp_min <= 8'd255;\n                        tmp_cnt <= 32'd0;\n                        prev_state <= 8'd0;\n                        next_state <= LOOP_PREV;\n                    end\n                    else begin\n                        next_state <= NEXT_COLUMN;\n                    end\n                end\n                \n                LOOP_PREV: begin\n                    if (prev_state >= state_limit) begin\n                        dp_new_min[cur_state] <= tmp_min;\n                        dp_new_cnt[cur_state] <= tmp_cnt;\n                        cur_state <= cur_state + 8'd1;\n                        next_state <= LOOP_CUR;\n                    end\n                    else if (valid_transition[prev_state][cur_state]) begin\n                        next_state <= COMPUTE_CANDIDATE;\n                    end\n                    else begin\n                        prev_state <= prev_state + 8'd1;\n                    end\n                end\n                \n                COMPUTE_CANDIDATE: begin\n                    if (dp_prev_min[prev_state] != 8'd255) begin\n                        if ((dp_prev_min[prev_state] + popcount_cur) < tmp_min) begin\n                            tmp_min <= dp_prev_min[prev_state] + popcount_cur;\n                            tmp_cnt <= dp_prev_cnt[prev_state];\n                        end\n                        else if ((dp_prev_min[prev_state] + popcount_cur) == tmp_min) begin\n                            tmp_cnt <= (tmp_cnt + dp_prev_cnt[prev_state]) % p;\n                        end\n                    end\n                    prev_state <= prev_state + 8'd1;\n                    next_state <= LOOP_PREV;\n                end\n                \n                NEXT_COLUMN: begin\n                    // Copy dp_new to dp_prev\n                    for (i = 0; i < STATE_COUNT; i = i + 1) begin\n                        dp_prev_min[i] <= dp_new_min[i];\n                        dp_prev_cnt[i] <= dp_new_cnt[i];\n                        dp_new_min[i] <= 8'd255;\n                        dp_new_cnt[i] <= 32'd0;\n                    end\n                    \n                    col_index <= col_index + 8'd1;\n                    cur_state <= 8'd0;\n                    if (col_index >= m) begin\n                        next_state <= FINALIZE;\n                    end\n                    else begin\n                        next_state <= LOOP_CUR;\n                    end\n                end\n                \n                FINALIZE: begin\n                    if (calc_state_i < state_limit) begin\n                        if (dp_prev_min[calc_state_i] < global_min) begin\n                            global_min <= dp_prev_min[calc_state_i];\n                            global_cnt <= dp_prev_cnt[calc_state_i];\n                        end\n                        else if (dp_prev_min[calc_state_i] == global_min) begin\n                            global_cnt <= (global_cnt + dp_prev_cnt[calc_state_i]) % p;\n                        end\n                        calc_state_i <= calc_state_i + 8'd1;\n                    end\n                    else begin\n                        result <= global_cnt;\n                        next_state <= DONE_ST;\n                    end\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        next_state <= IDLE;\n                        done <= 1'b0;\n                    end\n                end\n            endcase\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = current_state;\n        case (current_state)\n            IDLE:        next_state = start ? INIT_PRECOMP : IDLE;\n            INIT_PRECOMP: if (calc_state == 8'd0) next_state = INIT_PRECOMP;\n            DONE_ST:     if (!start) next_state = IDLE;\n            default: ;\n        endcase\n    end\n\nendmodule